export const CLASS_DATABASE = [...SRD_CLASSES, ...EXTENDED_CLASSES];

// ─── Lookup helpers ───────────────────────────────────────────────────────────
export const CLASS_BY_ID = Object.fromEntries(CLASS_DATABASE.map(c => [c.helpId, c]));
export const CLASS_BY_NAME = Object.fromEntries(CLASS_DATABASE.map(c => [c.name.toLowerCase(), c]));

export function getClassByHelpId(helpId) { return CLASS_BY_ID[helpId] || null; }
export function getClassByName(name) { return CLASS_BY_NAME[name?.toLowerCase()] || null; }

export const CLASS_SOURCES = [...new Set(CLASS_DATABASE.map(c => c.source))].sort();
export const BASE_CLASSES = CLASS_DATABASE.filter(c => c.classType !== 'Prestige');
export const PRESTIGE_CLASS_LIST = CLASS_DATABASE.filter(c => c.classType === 'Prestige');
